1	<script setup>
2	import { onMounted } from 'vue'
3	import { usePortfolioStore } from '@/stores/portfolio'
4	import { useTickerCurrency, useCurrency, usePercent, gainLossClass } from '@/composables/useFormat'
5	
6	const CURRENCY_SYMBOL = { USD: '$', ILS: '₪' }
7	import AllocationChart from '@/components/charts/AllocationChart.vue'
8	import SkeletonCard from '@/components/ui/SkeletonCard.vue'
9	
10	const portfolio = usePortfolioStore()
11	
12	onMounted(() => portfolio.fetchPortfolio())
13	</script>
14	
15	<template>
16	  <div class="dashboard">
17	    <header class="dash-header">
18	      <h1>Portfolio</h1>
19	    </header>
20	
21	    <div v-if="portfolio.loading" class="cards-grid">
22	      <SkeletonCard v-for="n in 4" :key="n" />
23	    </div>
24	
25	    <template v-else>
26	      <div
27	        v-for="t in portfolio.totals"
28	        :key="t.currency"
29	        class="summary-card"
30	      >
31	        <p class="summary-label">Total Value · {{ t.currency }}</p>
32	        <p class="summary-value">{{ useCurrency(t.value, t.currency) }}</p>
33	        <p class="summary-pnl" :class="gainLossClass(t.pnl)">
34	          {{ useCurrency(t.pnl, t.currency) }} ({{ usePercent(t.pnlPercent) }})
35	        </p>
36	      </div>
37	      <div v-if="!portfolio.totals.length && !portfolio.positions.length" class="summary-card">
38	        <p class="summary-label">Total Value</p>
39	        <p class="summary-value">$0.00</p>
40	      </div>
41	
42	      <AllocationChart :positions="portfolio.positions" />
43	
44	      <section class="section">
45	        <h2>Holdings</h2>
46	        <div
47	          v-for="pos in portfolio.positions"
48	          :key="pos.ticker"
49	          class="holding-row"
50	          @click="$router.push(`/stock/${pos.ticker}`)"
51	        >
52	          <div class="holding-left">
53	            <span class="ticker">{{ pos.ticker }}</span>
54	            <span class="company text-muted">{{ pos.companyName }}</span>
55	          </div>
56	          <div class="holding-right">
57	            <span class="price">{{ useTickerCurrency(pos.currentPrice, pos.ticker) }}</span>
58	            <span :class="gainLossClass(pos.changePercent)" class="change">
59	              {{ usePercent(pos.changePercent) }}
60	            </span>
61	          </div>
62	        </div>
63	        <p v-if="!portfolio.positions.length" class="empty text-muted">
64	          No holdings yet. Add a transaction to get started.
65	        </p>
66	      </section>
67	    </template>
68	  </div>
69	</template>
70	
71	<style scoped>
72	.dashboard { padding: 1rem; }
73	.dash-header { margin-bottom: 1.5rem; }
74	.dash-header h1 { font-size: 1.5rem; font-weight: 700; }
75	
76	.summary-card {
77	  background: var(--bg-card);
78	  border: 1px solid var(--border);
79	  border-radius: 16px;
80	  padding: 1.5rem;
81	  margin-bottom: 1rem;
82	  text-align: center;
83	}
84	.summary-label { font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 0.25rem; }
85	.summary-value { font-size: 2rem; font-weight: 700; }
86	.summary-pnl { font-size: 1rem; margin-top: 0.25rem; }
87	
88	.section { margin-top: 1.5rem; }
89	.section h2 { font-size: 1rem; font-weight: 600; margin-bottom: 0.75rem; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.05em; }
90	
91	.holding-row {
92	  display: flex;
93	  justify-content: space-between;
94	  align-items: center;
95	  padding: 0.85rem 0;
96	  border-bottom: 1px solid var(--border);
97	  cursor: pointer;
98	}
99	.holding-left { display: flex; flex-direction: column; gap: 2px; }
100	.holding-right { display: flex; flex-direction: column; align-items: flex-end; gap: 2px; }
101	.ticker { font-weight: 600; font-size: 1rem; }
102	.company { font-size: 0.8rem; }
103	.price { font-size: 0.95rem; }
104	.change { font-size: 0.85rem; }
105	.empty { padding: 1rem 0; font-size: 0.9rem; }
106	</style>
